import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
# flatten tools from api/tools? maybe huge; search names/ids
r=requests.get(f'{url}/api/tools', params={'key':key, 'in_panel':'false'})
print(r.status_code)
tools=r.json()
flat=[]
def rec(elems):
    for x in elems:
        if x.get('model_class')=='ToolSection': rec(x.get('elems') or [])
        else: flat.append(x)
rec(tools)
for term in ['cromwell','wdl','cwl','workflow','command','shell','exec','docker','container','atac','encode','nextflow']:
    matches=[t for t in flat if term in (t.get('id','')+' '+t.get('name','')+' '+str(t.get('description',''))).lower()]
    print('\\nTERM', term, 'n', len(matches))
    for t in matches[:30]: print(t.get('id'), '|', t.get('name'), '|', t.get('version'), '|', t.get('description'))
PY"

